(function() {
    const data = atob("").split(",");
    const audioBase64 = "";

    // Decodificación directa del audio en memoria RAM nativa (Inmune a CORS y bloqueos)
    const base64Clean = audioBase64.split(",") || audioBase64;
    const binaryString = atob(base64Clean);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    let audioBuffer = null;
    audioCtx.decodeAudioData(bytes.buffer).then(buf => {
        audioBuffer = buf;
    }).catch(err => console.error("Error decodificando audio:", err));

    const div = document.createElement('div');
    div.style = 'position:fixed; top:20px; left:20px; z-index:999999; background:#000; padding:15px; border-radius:10px; border:2px solid #333; text-align:center; box-shadow:0 10px 30px rgba(0,0,0,0.8);';
    
    const canvas = document.createElement('canvas');
    canvas.width = 320; canvas.height = 320;
    const ctx = canvas.getContext('2d');
    div.appendChild(canvas);

    const btn = document.createElement('button');
    btn.innerText = "INICIAR BAD APPLE ▶️";
    btn.style = "margin-top:10px;padding:8px 16px;background:#ff007f;color:#fff;border:none;border-radius:5px;font-weight:bold;cursor:pointer;font-family:sans-serif;font-size:12px;width:100%;box-shadow:0 4px 10px rgba(255,0,127,0.3);";
    div.appendChild(btn);
    document.body.appendChild(div);

    let f = 0, s = null, sourceNode = null;
    btn.onclick = () => {
        if (!audioBuffer) return alert("El audio todavía se está decodificando en memoria. Espera un segundo...");
        if (s) {
            clearInterval(s);
            if (sourceNode) sourceNode.stop();
            s = null;
            btn.innerText = "INICIAR BAD APPLE ▶️";
            btn.style.background = "#ff007f";
        } else {
            sourceNode = audioCtx.createBufferSource();
            sourceNode.buffer = audioBuffer;
            sourceNode.connect(audioCtx.destination);
            sourceNode.start();

            btn.innerText = "PAUSAR ⏸️";
            btn.style.background = "#00bfff";

            s = setInterval(() => {
                if (f >= data.length) {
                    clearInterval(s);
                    if (sourceNode) sourceNode.stop();
                    btn.innerText = "FIN 🔁";
                    btn.style.background = "#333";
                    f = 0; s = null;
                    return;
                }
                const h = data[f];
                ctx.fillStyle = '#000';
                ctx.fillRect(0, 0, 320, 320);
                ctx.fillStyle = '#fff';
                for (let i = 0; i < 32; i++) {
                    const b = parseInt(h.substr(i * 2, 2), 16);
                    for (let k = 0; k < 8; k++) {
                        if ((b >> (7 - k)) & 1) {
                            ctx.fillRect(((i * 8 + k) % 16) * 20, Math.floor((i * 8 + k) / 16) * 20, 20, 20);
                        }
                    }
                }
                f++;
            }, 33.3);
        }
    };
})();